import math
from numbers import Real


def smallest_prefix_for_share(values, share):
    if isinstance(share, bool) or not isinstance(share, Real):
        raise ValueError("share must be a real number")
    share = float(share)
    if not math.isfinite(share) or not 0 <= share <= 1:
        raise ValueError("share must be in [0, 1]")
    if isinstance(values, (str, bytes)):
        raise ValueError("values must be a numeric iterable")
    try:
        raw = list(values)
    except TypeError as exc:
        raise ValueError("values must be iterable") from exc
    normalized = []
    for value in raw:
        if isinstance(value, bool) or not isinstance(value, Real):
            raise ValueError("values must contain real numbers")
        number = float(value)
        if not math.isfinite(number) or number < 0:
            raise ValueError("values must be finite and non-negative")
        normalized.append(number)
    ordered = sorted(normalized, reverse=True)
    target = share * sum(ordered)
    if not ordered or target == 0:
        return []
    selected = []
    running = 0.0
    for number in ordered:
        selected.append(number)
        running += number
        if running > target:
            break
    return selected

