import math
import unittest

from solution import smallest_prefix_for_share


class OnceValues:
    def __init__(self, values):
        self.values = values
        self.calls = 0

    def __iter__(self):
        self.calls += 1
        if self.calls > 1:
            raise AssertionError("values consumed more than once")
        return iter(self.values)


class PrefixTests(unittest.TestCase):
    def test_shortest_prefix_uses_at_least_comparison(self):
        self.assertEqual(smallest_prefix_for_share([5, 3, 2], 0.5), [5.0])
        self.assertEqual(smallest_prefix_for_share([4, 3, 2, 1], 0.7), [4.0, 3.0])
        self.assertEqual(smallest_prefix_for_share([1, 2, 3], 1), [3.0, 2.0, 1.0])

    def test_empty_zero_total_and_zero_share(self):
        self.assertEqual(smallest_prefix_for_share([], 0.5), [])
        self.assertEqual(smallest_prefix_for_share([0, 0], 1), [])
        self.assertEqual(smallest_prefix_for_share([3, 2], 0), [])

    def test_does_not_mutate_input_and_returns_floats(self):
        values = [1, 4, 2]
        result = smallest_prefix_for_share(values, 0.5)
        self.assertEqual(values, [1, 4, 2])
        self.assertEqual(result, [4.0])
        self.assertTrue(all(type(value) is float for value in result))

    def test_consumes_generator_once_and_returns_fresh_lists(self):
        values = OnceValues([2, 1])
        first = smallest_prefix_for_share(values, 1)
        self.assertEqual(first, [2.0, 1.0])
        self.assertEqual(values.calls, 1)
        second = smallest_prefix_for_share([2, 1], 1)
        self.assertIsNot(first, second)
        first.append(9.0)
        self.assertEqual(second, [2.0, 1.0])

    def test_share_validation(self):
        for share in (True, False, -0.1, 1.1, math.inf, math.nan, "0.5", None):
            with self.subTest(share=share):
                with self.assertRaises(ValueError):
                    smallest_prefix_for_share([], share)

    def test_values_validation(self):
        cases = ["123", b"123", None, 3, [True], [False], [-1],
                 [math.inf], [math.nan], [1, "2"], [1, None]]
        for values in cases:
            with self.subTest(values=values):
                with self.assertRaises(ValueError):
                    smallest_prefix_for_share(values, 0.5)


if __name__ == "__main__":
    unittest.main()

